//! A scripted `Model` for deterministic replay.

use std::collections::VecDeque;
use std::path::Path;
use std::sync::{Arc, Mutex};

use async_trait::async_trait;
use futures_core::stream::BoxStream;
use futures_util::stream;
use paigasus_helikon_core::{
    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
};

use crate::{EvalError, ScriptFile};

/// A scripted [`Model`] that replays pre-recorded `ModelEvent`s: one
/// script per `invoke` call, in order. Running out of scripts yields a
/// `ModelError` — deterministic by construction.
pub struct MockModel {
    scripts: Mutex<VecDeque<Vec<ModelEvent>>>,
}

impl MockModel {
    /// A mock that answers exactly one `invoke` with `script`.
    pub fn with_script(script: Vec<ModelEvent>) -> Arc<Self> {
        Self::with_scripts(vec![script])
    }

    /// A mock that answers successive `invoke`s with successive scripts.
    pub fn with_scripts(scripts: Vec<Vec<ModelEvent>>) -> Arc<Self> {
        Arc::new(Self {
            scripts: Mutex::new(VecDeque::from(scripts)),
        })
    }

    /// Load the `default` scripts from a JSON script file. Files with
    /// only per-case entries yield an exhausted mock — use
    /// [`ScriptFile::load`] + [`ScriptFile::scripts_for`] for per-case
    /// selection.
    pub fn from_script_file(path: &Path) -> Result<Arc<Self>, EvalError> {
        let file = ScriptFile::load(path)?;
        Ok(Self::with_scripts(file.scripts_for("")))
    }
}

#[async_trait]
impl Model for MockModel {
    async fn invoke(
        &self,
        _request: ModelRequest,
        _cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        let script = self
            .scripts
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .pop_front()
            .ok_or_else(|| {
                ModelError::Other(anyhow::anyhow!("MockModel: no more scripted responses"))
            })?;
        Ok(Box::pin(stream::iter(script.into_iter().map(Ok))))
    }

    fn capabilities(&self) -> ModelCapabilities {
        ModelCapabilities::default()
    }

    fn provider(&self) -> &str {
        "mock"
    }
}

//! The [`Model`] trait — the single canonical async interface to an LLM
//! provider — and its carrier types.
//!
//! One trait covers OpenAI Chat Completions, OpenAI Responses, Anthropic
//! Messages, Bedrock Converse, and Gemini `FunctionDeclaration`. Capability
//! differences are surfaced via [`ModelCapabilities`], not split traits.

use async_trait::async_trait;
use futures_core::stream::BoxStream;

use crate::CancellationToken;

/// An LLM provider. The single canonical async interface.
///
/// One trait covers Chat Completions, Responses, Anthropic Messages,
/// Bedrock Converse, and Gemini `FunctionDeclaration`. Capability
/// differences are surfaced via [`ModelCapabilities`], not split traits.
///
/// # Example
///
/// ```
/// use async_trait::async_trait;
/// use futures_core::stream::BoxStream;
/// use paigasus_helikon_core::{
///     CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent,
///     ModelRequest,
/// };
///
/// struct NoopModel;
///
/// #[async_trait]
/// impl Model for NoopModel {
///     async fn invoke(
///         &self,
///         _request: ModelRequest,
///         _cancel: CancellationToken,
///     ) -> Result<
///         BoxStream<'static, Result<ModelEvent, ModelError>>,
///         ModelError,
///     > {
///         Err(ModelError::Unavailable)
///     }
///
///     fn capabilities(&self) -> ModelCapabilities {
///         ModelCapabilities::default()
///     }
/// }
/// ```
#[async_trait]
pub trait Model: Send + Sync {
    /// Invoke the model. Returns a stream of [`ModelEvent`]s on success or a
    /// [`ModelError`] if the request could not be sent. Individual events in
    /// the stream may themselves carry a [`ModelError`].
    ///
    /// **Event-ordering contract:**
    /// - `TokenDelta`, `ReasoningDelta`, and `ToolCallDelta` may interleave
    ///   freely while the model is generating.
    /// - `Usage` MAY appear anywhere; most providers emit one immediately
    ///   before `Finish`, while Anthropic emits cumulative-within-response
    ///   updates. Each `Usage` is a complete snapshot (last-wins): consumers
    ///   retain the last seen and never sum `Usage` events within a turn.
    ///   See [`ModelEvent::Usage`].
    /// - `Finish` is the terminal event; nothing follows it.
    /// - Implementations MUST emit `Finish` at end-of-stream when a stop
    ///   reason was observed, and MUST NOT emit it on truncation with no stop
    ///   reason observed, on cancellation, or after a mid-stream error.
    ///
    /// Implementations that cannot honor cancellation MUST still terminate
    /// the stream when the [`CancellationToken`] fires (drop the underlying
    /// connection and end the stream without emitting `Finish`).
    async fn invoke(
        &self,
        request: ModelRequest,
        cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError>;

    /// Provider capabilities. Stable across calls.
    fn capabilities(&self) -> ModelCapabilities;

    /// GenAI `gen_ai.provider.name` — the provider identifier (e.g.
    /// `"openai"`, `"anthropic"`). Providers override this; the `"unknown"`
    /// default is only recorded for a `Model` that does not.
    fn provider(&self) -> &str {
        "unknown"
    }

    /// GenAI `gen_ai.request.model` — the configured model id (e.g.
    /// `"gpt-4o"`). Providers override this; the empty default is only
    /// recorded for a `Model` that does not.
    fn model(&self) -> &str {
        ""
    }
}

/// The request envelope crossing the model boundary.
///
/// Carries the conversation, the tools available for the model to
/// invoke, and provider-tuning knobs. Field shape is the minimum SMA-314
/// needs to drive the loop; SMA-316 / SMA-317 add `tool_choice`,
/// `response_format`, `temperature`, and `previous_response_id`.
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub struct ModelRequest {
    /// The full accumulated conversation so far.
    pub messages: Vec<crate::Item>,
    /// Tool definitions the model may invoke this turn.
    pub tools: Vec<ToolDef>,
    /// Provider-tuning knobs.
    pub model_settings: ModelSettings,
}

impl ModelRequest {
    /// Construct an empty request. Callers populate fields directly.
    pub fn new() -> Self {
        Self::default()
    }
}

/// Owned snapshot of a [`crate::Tool`] for cross-async-boundary use
/// inside [`ModelRequest`].
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ToolDef {
    /// Identifier the model uses when emitting a tool call.
    pub name: String,
    /// One-line tool description shown to the model.
    pub description: String,
    /// JSON Schema for the tool's argument object.
    pub schema: serde_json::Value,
}

/// Provider-tuning knobs.
///
/// Field shape grew in SMA-316 to cover the surface OpenAI needs;
/// SMA-317 (Anthropic) may reshape if Anthropic's protocol demands it.
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub struct ModelSettings {
    /// Sampling temperature. Provider-defined default when unset.
    pub temperature: Option<f32>,
    /// Nucleus-sampling top-p. Provider-defined default when unset.
    pub top_p: Option<f32>,
    /// Cap on output tokens per response. Maps to `max_tokens` on
    /// OpenAI Chat and to `max_output_tokens` on OpenAI Responses.
    pub max_output_tokens: Option<u32>,
    /// Caller's tool-selection preference. See [`ToolChoice`].
    pub tool_choice: Option<ToolChoice>,
    /// Caller's response-shape preference. See [`ResponseFormat`].
    pub response_format: Option<ResponseFormat>,
    /// OpenAI Responses-API server-side state token. **Caller-managed:**
    /// when set, callers MUST trim [`ModelRequest::messages`] to only
    /// the items added since the response identified by this id. The
    /// provider passes `messages` through as-is — it does not filter.
    /// Integration with [`crate::LlmAgent`]'s automatic conversation
    /// accumulation is out of scope for SMA-316; see follow-up ticket.
    /// Ignored by non-OpenAI-Responses providers.
    pub previous_response_id: Option<String>,
}

impl ModelSettings {
    /// Construct default model settings (all fields unset).
    pub fn new() -> Self {
        Self::default()
    }
}

/// Streaming union — token / reasoning / tool-call deltas, usage snapshots, finish.
///
/// See ADR-1 (*Single Model trait with capabilities flags*).
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum ModelEvent {
    /// A chunk of assistant text.
    TokenDelta {
        /// The text fragment.
        text: String,
    },
    /// A chunk of reasoning/scratchpad text (for providers that emit it
    /// separately from the assistant text channel).
    ReasoningDelta {
        /// The text fragment.
        text: String,
    },
    /// A partial tool call. `name` is `Some` exactly once per `call_id`, on
    /// the first delta for which the provider can establish the name is
    /// complete, and `None` on every other delta. When `Some`, the value is
    /// the whole name so far as the provider can determine — a provider
    /// receiving the name in fragments MUST buffer and concatenate them, and
    /// MUST NOT emit a name it can detect is still incomplete.
    ToolCallDelta {
        /// Provider-assigned identifier for the call.
        call_id: String,
        /// `Some` exactly once per `call_id`, on the first delta for which
        /// the provider can establish the name is complete, and `None` on
        /// every other delta. When `Some`, the value is the whole name so
        /// far as the provider can determine — a provider receiving the
        /// name in fragments MUST buffer and concatenate them, and MUST NOT
        /// emit a name it can detect is still incomplete.
        name: Option<String>,
        /// JSON-encoded argument fragment.
        args_delta: String,

//! `Interceptors`: the run's control-layer orchestration unit.
//!
//! Borrows the stream-local Arc-snapshots of the agent's guardrails/hooks and
//! the run's [`RunContext`] (mode, policy, deny rules, approval handler). The
//! driver calls its async methods at the loop's control seams. Pure of the
//! state machine — all async control lives here, not in `transition()`.

use std::sync::Arc;

use crate::{
    Guardrail, Hook, HookDecision, HookEvent, HookRegistry, PermissionDecision, RunContext,
    ToolEffect,
};

/// Borrows everything the control seams need for one run.
pub(crate) struct Interceptors<'a, Ctx>
where
    Ctx: Send + Sync + 'static,
{
    pub(crate) ctx: &'a RunContext<Ctx>,
    pub(crate) input_guardrails: &'a [Arc<dyn Guardrail<Ctx>>],
    pub(crate) output_guardrails: &'a [Arc<dyn Guardrail<Ctx>>],
    pub(crate) agent_hooks: &'a [Arc<dyn Hook<Ctx>>],
}

/// The folded outcome of firing all hooks for one event.
#[derive(Debug, Default)]
pub(crate) struct ResolvedHookDecision {
    /// `Some(reason)` if any hook denied (first wins).
    pub(crate) denied: Option<String>,
    /// The last `ReplaceInput`/`ReplaceOutput` value, if any.
    pub(crate) replacement: Option<serde_json::Value>,
    /// All injected system messages, in fire order.
    pub(crate) injections: Vec<String>,
}

impl<'a, Ctx> Interceptors<'a, Ctx>
where
    Ctx: Send + Sync + 'static,
{
    /// Fire `event` to agent-level hooks first, then the run-level
    /// [`HookRegistry`]. Folds outcomes: first `Deny` short-circuits;
    /// `Replace*` last-writer-wins; `InjectSystemMessage` accumulates.
    pub(crate) async fn fire(&self, event: &HookEvent) -> ResolvedHookDecision {
        let mut out = ResolvedHookDecision::default();
        let registry: &HookRegistry<Ctx> = self.ctx.hooks();
        let all = self.agent_hooks.iter().chain(registry.iter());
        for hook in all {
            match hook.on_event(self.ctx, event).await {
                HookDecision::Allow => {}
                HookDecision::Deny { reason } => {
                    out.denied = Some(reason);
                    return out; // short-circuit
                }
                HookDecision::ReplaceInput { value } | HookDecision::ReplaceOutput { value } => {
                    out.replacement = Some(value);
                }
                HookDecision::InjectSystemMessage { text } => {
                    out.injections.push(text);
                }
            }
        }
        out
    }

    /// Run input guardrails as a blocking gate. Returns `Some((kind, info))`
    /// on the first tripwire, else `None`. A guardrail's own error is treated
    /// as a tripwire with [`crate::GuardrailKind::Other`].
    pub(crate) async fn run_input_guardrails(
        &self,
        text: &str,
    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
        self.run_guardrails(self.input_guardrails, crate::GuardrailInput::UserText(text))
            .await
    }

    /// Run output guardrails as a blocking gate on the final text.
    pub(crate) async fn run_output_guardrails(
        &self,
        text: &str,
    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
        self.run_guardrails(
            self.output_guardrails,
            crate::GuardrailInput::ModelOutput(text),
        )
        .await
    }

    async fn run_guardrails(
        &self,
        guardrails: &[Arc<dyn Guardrail<Ctx>>],
        input: crate::GuardrailInput<'_>,
    ) -> Option<(crate::GuardrailKind, serde_json::Value)> {
        for g in guardrails {
            match g.check(self.ctx, input.clone()).await {
                Ok(crate::GuardrailVerdict::Pass) => {}
                Ok(crate::GuardrailVerdict::Tripwire { kind, info }) => return Some((kind, info)),
                Err(e) => {
                    return Some((
                        crate::GuardrailKind::Other {
                            reason: e.to_string(),
                        },
                        serde_json::Value::Null,
                    ))
                }
            }
        }
        None
    }

    /// Authorize one tool call on its effective args: `deny rules › guard rules ›
    /// allow rules › mode › policy › AskUser`. Returns the resolved decision
    /// (never `AskUser` — that is resolved here via the approval handler, default
    /// Deny). Delegates to `RunContext::authorize_tool` — the primitive a
    /// durable runner calls directly without needing this loop-private borrow.
    pub(crate) async fn authorize(
        &self,
        tool: &str,
        effect: ToolEffect,
        args: &serde_json::Value,
    ) -> PermissionDecision {
        self.ctx.authorize_tool(tool, effect, args).await
    }
}

